CREATE TABLE StudyProject (Id TEXT NOT NULL PRIMARY KEY, CreatedAtUtc TEXT NOT NULL, UpdatedAtUtc TEXT NOT NULL, Revision INTEGER NOT NULL DEFAULT 1 CHECK(Revision > 0), Name TEXT NOT NULL CHECK(length(trim(Name)) BETWEEN 1 AND 120), Description TEXT NOT NULL DEFAULT '' CHECK(length(Description) <= 2000), Color TEXT NOT NULL, IconKey TEXT NOT NULL, IsFavorite INTEGER NOT NULL DEFAULT 0 CHECK(IsFavorite IN (0,1)));
CREATE INDEX IX_Project_Modified ON StudyProject(UpdatedAtUtc DESC, Id);
CREATE TABLE Tag (Id TEXT NOT NULL PRIMARY KEY, CreatedAtUtc TEXT NOT NULL, UpdatedAtUtc TEXT NOT NULL, Revision INTEGER NOT NULL DEFAULT 1 CHECK(Revision > 0), ProjectId TEXT NOT NULL, Name TEXT NOT NULL, NormalizedName TEXT NOT NULL, UNIQUE(ProjectId, Id), FOREIGN KEY(ProjectId) REFERENCES StudyProject(Id) ON DELETE CASCADE, UNIQUE(ProjectId, NormalizedName));
CREATE TABLE ProjectTag (ProjectId TEXT NOT NULL, TagId TEXT NOT NULL, CreatedAtUtc TEXT NOT NULL, PRIMARY KEY(ProjectId, TagId), FOREIGN KEY(ProjectId, TagId) REFERENCES Tag(ProjectId, Id) ON DELETE CASCADE);
CREATE TABLE StudySource (Id TEXT NOT NULL PRIMARY KEY, CreatedAtUtc TEXT NOT NULL, UpdatedAtUtc TEXT NOT NULL, Revision INTEGER NOT NULL DEFAULT 1 CHECK(Revision > 0), ProjectId TEXT NOT NULL, Title TEXT NOT NULL, Kind INTEGER NOT NULL CHECK(Kind BETWEEN 0 AND 4), OriginalFileName TEXT, CurrentRevisionId TEXT, IsArchived INTEGER NOT NULL DEFAULT 0, UNIQUE(ProjectId, Id), FOREIGN KEY(ProjectId) REFERENCES StudyProject(Id) ON DELETE CASCADE, FOREIGN KEY(ProjectId, Id, CurrentRevisionId) REFERENCES SourceRevision(ProjectId, SourceId, Id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE SourceRevision (Id TEXT NOT NULL PRIMARY KEY, CreatedAtUtc TEXT NOT NULL, UpdatedAtUtc TEXT NOT NULL, Revision INTEGER NOT NULL DEFAULT 1 CHECK(Revision > 0), ProjectId TEXT NOT NULL, SourceId TEXT NOT NULL, Number INTEGER NOT NULL CHECK(Number > 0), RelativeFilePath TEXT, ContentHash TEXT NOT NULL DEFAULT '', ExtractedText TEXT NOT NULL DEFAULT '', ExtractorVersion TEXT NOT NULL DEFAULT '1', Status INTEGER NOT NULL DEFAULT 0, ErrorCode TEXT, UNIQUE(ProjectId, Id), FOREIGN KEY(ProjectId) REFERENCES StudyProject(Id) ON DELETE CASCADE, FOREIGN KEY(ProjectId, SourceId) REFERENCES StudySource(ProjectId, Id) ON DELETE CASCADE, UNIQUE(SourceId, Number), UNIQUE(ProjectId, SourceId, Id));
CREATE TABLE SourceChunk (Id TEXT NOT NULL PRIMARY KEY, CreatedAtUtc TEXT NOT NULL, UpdatedAtUtc TEXT NOT NULL, Revision INTEGER NOT NULL DEFAULT 1 CHECK(Revision > 0), ProjectId TEXT NOT NULL, SourceRevisionId TEXT NOT NULL, Ordinal INTEGER NOT NULL CHECK(Ordinal >= 0), Text TEXT NOT NULL, StartOffset INTEGER NOT NULL CHECK(StartOffset >= 0), EndOffset INTEGER NOT NULL CHECK(EndOffset >= StartOffset), PageStart INTEGER, PageEnd INTEGER, SectionPath TEXT, ChunkerVersion TEXT NOT NULL DEFAULT '1', UNIQUE(ProjectId, Id), FOREIGN KEY(ProjectId) REFERENCES StudyProject(Id) ON DELETE CASCADE, FOREIGN KEY(ProjectId, SourceRevisionId) REFERENCES SourceRevision(ProjectId, Id) ON DELETE CASCADE, UNIQUE(SourceRevisionId, Ordinal));
CREATE TABLE FlashCard (Id TEXT NOT NULL PRIMARY KEY, CreatedAtUtc TEXT NOT NULL, UpdatedAtUtc TEXT NOT NULL, Revision INTEGER NOT NULL DEFAULT 1 CHECK(Revision > 0), ProjectId TEXT NOT NULL, Front TEXT NOT NULL, Back TEXT NOT NULL, Explanation TEXT, Difficulty INTEGER, IsFavorite INTEGER NOT NULL DEFAULT 0, UNIQUE(ProjectId, Id), FOREIGN KEY(ProjectId) REFERENCES StudyProject(Id) ON DELETE CASCADE);
CREATE TABLE Topic (Id TEXT NOT NULL PRIMARY KEY, CreatedAtUtc TEXT NOT NULL, UpdatedAtUtc TEXT NOT NULL, Revision INTEGER NOT NULL DEFAULT 1 CHECK(Revision > 0), ProjectId TEXT NOT NULL, Name TEXT NOT NULL, NormalizedName TEXT NOT NULL, UNIQUE(ProjectId, Id), FOREIGN KEY(ProjectId) REFERENCES StudyProject(Id) ON DELETE CASCADE, UNIQUE(ProjectId, NormalizedName));
CREATE TABLE Quiz (Id TEXT NOT NULL PRIMARY KEY, CreatedAtUtc TEXT NOT NULL, UpdatedAtUtc TEXT NOT NULL, Revision INTEGER NOT NULL DEFAULT 1 CHECK(Revision > 0), ProjectId TEXT NOT NULL, Title TEXT NOT NULL, Mode INTEGER NOT NULL CHECK(Mode BETWEEN 0 AND 2), RequestedCount INTEGER NOT NULL CHECK(RequestedCount > 0), Difficulty INTEGER NOT NULL, IsArchived INTEGER NOT NULL DEFAULT 0, UNIQUE(ProjectId, Id), FOREIGN KEY(ProjectId) REFERENCES StudyProject(Id) ON DELETE CASCADE);
CREATE TABLE QuizQuestion (Id TEXT NOT NULL PRIMARY KEY, CreatedAtUtc TEXT NOT NULL, UpdatedAtUtc TEXT NOT NULL, Revision INTEGER NOT NULL DEFAULT 1 CHECK(Revision > 0), ProjectId TEXT NOT NULL, QuizId TEXT NOT NULL, Position INTEGER NOT NULL CHECK(Position >= 0), Kind INTEGER NOT NULL CHECK(Kind IN (0,1)), Prompt TEXT NOT NULL, Explanation TEXT NOT NULL DEFAULT '', IdealAnswer TEXT NOT NULL DEFAULT '', RubricJson TEXT NOT NULL DEFAULT '[]', Difficulty INTEGER NOT NULL, UNIQUE(ProjectId, Id), FOREIGN KEY(ProjectId) REFERENCES StudyProject(Id) ON DELETE CASCADE, FOREIGN KEY(ProjectId, QuizId) REFERENCES Quiz(ProjectId, Id) ON DELETE CASCADE, UNIQUE(QuizId, Position));
CREATE TABLE QuestionOption (Id TEXT NOT NULL PRIMARY KEY, CreatedAtUtc TEXT NOT NULL, UpdatedAtUtc TEXT NOT NULL, Revision INTEGER NOT NULL DEFAULT 1 CHECK(Revision > 0), ProjectId TEXT NOT NULL, QuestionId TEXT NOT NULL, Position INTEGER NOT NULL, Text TEXT NOT NULL, IsCorrect INTEGER NOT NULL CHECK(IsCorrect IN (0,1)), UNIQUE(ProjectId, Id), FOREIGN KEY(ProjectId) REFERENCES StudyProject(Id) ON DELETE CASCADE, FOREIGN KEY(ProjectId, QuestionId) REFERENCES QuizQuestion(ProjectId, Id) ON DELETE CASCADE, UNIQUE(QuestionId, Position));
CREATE TABLE QuizAttempt (Id TEXT NOT NULL PRIMARY KEY, CreatedAtUtc TEXT NOT NULL, UpdatedAtUtc TEXT NOT NULL, Revision INTEGER NOT NULL DEFAULT 1 CHECK(Revision > 0), ProjectId TEXT NOT NULL, QuizId TEXT, Mode INTEGER NOT NULL, Difficulty INTEGER NOT NULL, Status INTEGER NOT NULL DEFAULT 0, StartedAtUtc TEXT NOT NULL, SubmittedAtUtc TEXT, CompletedAtUtc TEXT, ActiveDurationMs INTEGER NOT NULL DEFAULT 0 CHECK(ActiveDurationMs >= 0), Score REAL, MaximumScore INTEGER NOT NULL CHECK(MaximumScore > 0), ScoringVersion INTEGER NOT NULL DEFAULT 1, UNIQUE(ProjectId, Id), FOREIGN KEY(ProjectId) REFERENCES StudyProject(Id) ON DELETE CASCADE, FOREIGN KEY(ProjectId, QuizId) REFERENCES Quiz(ProjectId, Id), CHECK(Score IS NULL OR (Score >= 0 AND Score <= MaximumScore)));
CREATE TABLE AttemptQuestion (Id TEXT NOT NULL PRIMARY KEY, CreatedAtUtc TEXT NOT NULL, UpdatedAtUtc TEXT NOT NULL, Revision INTEGER NOT NULL DEFAULT 1 CHECK(Revision > 0), ProjectId TEXT NOT NULL, AttemptId TEXT NOT NULL, OriginalQuestionId TEXT, Position INTEGER NOT NULL, SnapshotJson TEXT NOT NULL, SnapshotSchemaVersion INTEGER NOT NULL DEFAULT 1, UNIQUE(ProjectId, Id), FOREIGN KEY(ProjectId) REFERENCES StudyProject(Id) ON DELETE CASCADE, FOREIGN KEY(ProjectId, AttemptId) REFERENCES QuizAttempt(ProjectId, Id) ON DELETE CASCADE, UNIQUE(AttemptId, Position));
CREATE TABLE QuizAnswer (Id TEXT NOT NULL PRIMARY KEY, CreatedAtUtc TEXT NOT NULL, UpdatedAtUtc TEXT NOT NULL, Revision INTEGER NOT NULL DEFAULT 1 CHECK(Revision > 0), ProjectId TEXT NOT NULL, AttemptQuestionId TEXT NOT NULL, Text TEXT, SelectedOptionId TEXT, AnswerRevision INTEGER NOT NULL DEFAULT 1 CHECK(AnswerRevision > 0), AnsweredAtUtc TEXT, EvaluationStatus INTEGER NOT NULL DEFAULT 0, UNIQUE(ProjectId, Id), FOREIGN KEY(ProjectId) REFERENCES StudyProject(Id) ON DELETE CASCADE, FOREIGN KEY(ProjectId, AttemptQuestionId) REFERENCES AttemptQuestion(ProjectId, Id) ON DELETE CASCADE, UNIQUE(AttemptQuestionId), CHECK(Text IS NULL OR SelectedOptionId IS NULL));
CREATE TABLE StudyWeakness (Id TEXT NOT NULL PRIMARY KEY, CreatedAtUtc TEXT NOT NULL, UpdatedAtUtc TEXT NOT NULL, Revision INTEGER NOT NULL DEFAULT 1 CHECK(Revision > 0), ProjectId TEXT NOT NULL, AttemptId TEXT NOT NULL, TopicId TEXT NOT NULL, EarnedScore REAL NOT NULL CHECK(EarnedScore >= 0), MaximumScore REAL NOT NULL CHECK(MaximumScore > 0), EvidenceCount INTEGER NOT NULL CHECK(EvidenceCount > 0), DetailsJson TEXT NOT NULL DEFAULT '{}', UNIQUE(ProjectId, Id), FOREIGN KEY(ProjectId) REFERENCES StudyProject(Id) ON DELETE CASCADE, FOREIGN KEY(ProjectId, AttemptId) REFERENCES QuizAttempt(ProjectId, Id) ON DELETE CASCADE, FOREIGN KEY(ProjectId, TopicId) REFERENCES Topic(ProjectId, Id) ON DELETE CASCADE, UNIQUE(AttemptId, TopicId), CHECK(EarnedScore <= MaximumScore));
CREATE TABLE SourceTag (ProjectId TEXT NOT NULL, SourceId TEXT NOT NULL, TagId TEXT NOT NULL, PRIMARY KEY(ProjectId, SourceId, TagId), FOREIGN KEY(ProjectId, SourceId) REFERENCES StudySource(ProjectId, Id) ON DELETE CASCADE, FOREIGN KEY(ProjectId, TagId) REFERENCES Tag(ProjectId, Id) ON DELETE CASCADE);
CREATE TABLE FlashcardTag (ProjectId TEXT NOT NULL, FlashcardId TEXT NOT NULL, TagId TEXT NOT NULL, PRIMARY KEY(ProjectId, FlashcardId, TagId), FOREIGN KEY(ProjectId, FlashcardId) REFERENCES FlashCard(ProjectId, Id) ON DELETE CASCADE, FOREIGN KEY(ProjectId, TagId) REFERENCES Tag(ProjectId, Id) ON DELETE CASCADE);
CREATE TABLE FlashcardCitation (ProjectId TEXT NOT NULL, FlashcardId TEXT NOT NULL, ChunkId TEXT NOT NULL, PRIMARY KEY(ProjectId, FlashcardId, ChunkId), FOREIGN KEY(ProjectId, FlashcardId) REFERENCES FlashCard(ProjectId, Id) ON DELETE CASCADE, FOREIGN KEY(ProjectId, ChunkId) REFERENCES SourceChunk(ProjectId, Id) ON DELETE CASCADE);
CREATE TABLE QuestionCitation (ProjectId TEXT NOT NULL, QuestionId TEXT NOT NULL, ChunkId TEXT NOT NULL, PRIMARY KEY(ProjectId, QuestionId, ChunkId), FOREIGN KEY(ProjectId, QuestionId) REFERENCES QuizQuestion(ProjectId, Id) ON DELETE CASCADE, FOREIGN KEY(ProjectId, ChunkId) REFERENCES SourceChunk(ProjectId, Id) ON DELETE CASCADE);
CREATE INDEX IX_Attempt_Project_Date ON QuizAttempt(ProjectId, StartedAtUtc DESC);
CREATE INDEX IX_SourceRevision_Parent ON SourceRevision(ProjectId, SourceId);
CREATE INDEX IX_SourceChunk_Parent ON SourceChunk(ProjectId, SourceRevisionId);
CREATE INDEX IX_QuizQuestion_Parent ON QuizQuestion(ProjectId, QuizId);
CREATE INDEX IX_QuestionOption_Parent ON QuestionOption(ProjectId, QuestionId);
CREATE INDEX IX_AttemptQuestion_Parent ON AttemptQuestion(ProjectId, AttemptId);
CREATE INDEX IX_StudyWeakness_Parent ON StudyWeakness(ProjectId, TopicId);

